OUT = ROOT / 'geometry-course/textbook/data/coordinate-positions.json'
O = (0, 0)


def panel(label, vertices, sides='', arrows='', right=()):
    """Draw geometry with named vertices, coordinate grid and marks for prescribed angles."""
    _, points, axes, grid_lines = grid(label, [(name, O, pos) for name, pos in vertices.items()])
    points = {name: pos for name, pos in points.items() if name.startswith('_') or name in ('O', 'X', 'Y')}
    points.update(vertices)
    def edges(pairs):
        return [tuple(pair) for pair in pairs.split()]
    return (label, points, axes[:2] + edges(arrows), grid_lines + edges(sides)), right


def lesson(n, *, pages, frames, cases, unit='1 единица', part=None, **fields):
    views = frames + cases
    entry = authored(n, chapter_part=part, pages=pages, frames=[frame for frame, _ in frames],
                     cases=[frame for frame, _ in cases], **fields)
    entry['review']['reviewer'] = 'Атанасян 7–9, 2023. Исходные страницы, нумерация и обозначения сверены с книгой; координаты, углы и перемещения проверены измерениями собственной модели.'
    if entry['kind'] == 'exercise':
        entry['help'][1].update(theoryIds=['atanasyan-7-9-theory-95-part-1', 'atanasyan-7-9-theory-96-part-1'],
                               text='Выбери формулу по тому, что ищешь: точку, её смещение или длину. Проверь по отдельности горизонтальную и вертикальную составляющие.')
        entry['answer']['prompt'] = 'Запиши координаты с названиями всех требуемых точек и объясни условие, по которому ты их нашёл.'
    model = entry['visualization']['model']
    for ((_, _, arrows, _), marks), (key, view) in zip(views, model['views'].items(), strict=True):
        suffix = '__v' + view['points'][0].split('__v')[1]
        view['points'] = [name for name in view['points'] if not name.startswith('_')]
        view['dashSegments'] = [pair for pair in view['segments'] if pair[0].startswith(('_gx', '_gy'))]
        view['segments'] = [pair for pair in view['segments'] if pair not in view['dashSegments']]
        highlight = [[a + suffix, b + suffix] for a, b in arrows[2:]]
        highlight.extend(pair for pair in view['segments'] if pair[1].startswith('head_') and int(pair[1].split('_')[2]) >= 2)
        view['highlightSegments'] = highlight
        view['rightAngles'] = [dict(vertex=b + suffix, a=a + suffix, b=c + suffix, size=2) for a, b, c in marks]
        labels = {name for pair in view['segments'] + view['dashSegments'] for name in pair} | set(view['points'])
        labels.update('_unit' + axis + suffix for axis in 'XY')
        positions = [model['points'][name] for name in labels]
        xs, ys = zip(*[point[:2] for point in positions], strict=True)
        center = ((min(xs) + max(xs))/2, (min(ys) + max(ys))/2)
        fit = min(70/(max(xs)-min(xs)), 48/(max(ys)-min(ys)))
        for point in positions:
            point[0] = 50 + (point[0]-center[0])*fit
            point[1] = 35 + (point[1]-center[1])*fit
    for name, label in model['labels'].items():
        if label in ('X','Y'):
            model['labels'][name] = label.lower()
            # Put axis names on the outside of each axis, away from vertices on it.
            model.setdefault('labelOffsets', {})[name] = [2,-3.5] if label=='X' else [-2.2,2.7]
    caption = f'Масштаб одной клетки — {unit}. Вправо возрастает x, вверх — y. Сверь положение каждой точки относительно осей.'
    entry['visualization']['caption'] = caption
    model['description'] = caption
    return entry


def formulas():
    a = panel('От начала координат', {'M':(-2,3),'H':(-2,0)}, 'OH HM', 'OM', ['OHM'])
    b = panel('Новое начало в точке A', {'A':(-2,1),'B':(3,-1)}, '', 'OA OB AB')
    c = panel('Поверни стрелку обратно', {'A':(-2,1),'B':(3,-1)}, '', 'BA')
    p95 = lesson(95, title='Связь между координатами вектора и координатами его начала и конца', pages=[252,253,254],
        question='Почему координаты точки M совпадают с координатами вектора OM? Как по двум точкам A и B вычислить координаты направленного отрезка AB?',
        answer='Разложи радиус-вектор OM на перемещения по осям. Их подписанные длины равны абсциссе и ординате M. Из OA+AB=OB следует AB=OB−OA. Для A=(x₁;y₁) и B=(x₂;y₂) получаем AB=(x₂−x₁;y₂−y₁).',
        hint='Представь два маршрута из O в B: прямой и через A. Их общее смещение одинаково.',
        steps=[('Прочитай проекции','Чтобы попасть из O в M=(−2;3), пройди две единицы влево и три вверх. Знаки проекций определяют направление. Точка на оси даёт ноль по другой координате.','Разложение по единичным векторам i и j единственно.'),
               ('Вычти начало из конца','Для A=(−2;1), B=(3;−1) путь AB проходит 3−(−2)=5 вправо и −1−1=−2 по вертикали. Получился вектор (5;−2).','Из правила треугольника AB=OB−OA.'),
               ('Обрати направление','У BA началом стала B, концом A. Обе координаты меняют знак: (−5;2). Для совпадающих точек вышло бы (0;0).','Обратный маршрут компенсирует первоначальный.')],
        frames=[a,a,b,c], cases=[a,b,c], prompts=[('Какова абсцисса AB при xA=−2 и xB=3?', '5','Конец минус начало: 3−(−2).'),
        ('На новом чертеже yA=4, yB=−3. Найди ординату BA.', '7','У BA конец A, поэтому вычисли 4−(−3).')])
    d = panel('Точка делит отрезок пополам',{'A':(-2,1),'B':(4,3),'M':(1,2)},'AB')
    e = panel('Длина вектора',{'P':(3,-4),'H':(3,0)},'OH HP','OP',['OHP'])
    f = panel('Длина между двумя точками',{'A':(-2,1),'B':(2,4),'H':(2,1)},'AH HB AB','',['AHB'])
    p96 = lesson(96,title='Простейшие задачи в координатах',pages=[254,255],
        question='Как по концам отрезка найти середину и длину? Как связана длина произвольного вектора с его координатами? Объясни все три формулы.',
        answer='Середина M имеет координаты ((xA+xB)/2;(yA+yB)/2). Длина вектора (u;v) равна √(u²+v²). Для расстояния AB подставь разности координат: √((xB−xA)²+(yB−yA)²).',
        hint='Середина делит каждую проекцию пополам. Для длины используй прямоугольный треугольник с горизонтальным и вертикальным катетами.',
        steps=[('Усредни координаты','Для A=(−2;1), B=(4;3) получаем M=(1;2). От A к M и от M к B сдвигаемся на (3;1). В общем виде складываем одноимённые координаты, затем делим на два.','Радиус-вектор середины равен полусумме радиус-векторов концов.'),
               ('Найди длину вектора','У (3;−4) длины проекций 3 и 4. По теореме Пифагора длина равна 5. Для (u;v) получаем √(u²+v²); при нулевой проекции остаётся модуль другой.','Оси перпендикулярны, поэтому квадраты длин катетов складываются.'),
               ('Вычисли расстояние','От A=(−2;1) к B=(2;4) смещение равно (4;3), расстояние равно 5. При перестановке точек знаки изменятся, а квадраты и расстояние сохранятся.','Расстояние двух точек равно длине их соединяющего вектора.')],
        frames=[d,d,e,f],cases=[d,e,f],prompts=[('Какова длина вектора (3;−4)?','5','Найди квадратный корень из 9+16.'),('В новом отрезке середина имеет y=−1, первый конец y=4. Найди y второго конца.','-6','Пусть yB=t. Тогда (4+t)/2=−1.')])
    return [p95,p96]


def axes():
    def triangle(x,y,full):
        pts={'A':(x,0),'B':(0,y)}
        return panel(f'Треугольник: OA={x}, OB={y}' if full else 'Две положительные полуоси',pts,'OA OB AB' if full else 'OA OB','',['AOB'])
    a=triangle(5,3,False); b=triangle(5,3,True); c=triangle(2,4,True)
    first=lesson(1016,part='а',pages=[255],question='Точки A и B лежат соответственно на положительных полуосях Ox и Oy. Найди координаты вершин треугольника ABO, если OA=5 и OB=3.',
        answer='A=(5;0), B=(0;3), O=(0;0). Первая точка имеет нулевую ординату, вторая — нулевую абсциссу.',
        hint='Сначала выпиши координату, которая равна нулю у каждой вершины. Положительная полуось подсказывает знак оставшейся.',
        steps=[('Найди вершину O','Оси пересекаются в начале координат, значит O=(0;0). Горизонтальная сторона идёт вправо от O, вертикальная вверх.','Ни один из двух отсчётов в начале координат ещё не изменился.'),
               ('Отметь две вершины','A находится на пять клеток правее O и на той же высоте, поэтому A=(5;0). Для B поднимись на три клетки от O, сохранив x=0.','Абсцисса отсчитывается вдоль Ox, ордината — вдоль Oy.'),
               ('Проверь по сторонам','Вычисли OA и OB как расстояния вдоль осей: 5 и 3. При OA=2 и OB=4 метод даёт A=(2;0), B=(0;4).','Координаты точек на положительных полуосях неотрицательны.')],
        frames=[a,a,b,c],cases=[a,b,c],prompts=[('Какова ордината точки A?','0','Точка A находится на Ox.'),('В новом треугольнике OB=4. Чему равна ордината B?','4','Двигаемся на четыре клетки вверх от O.')])
    def rectangle(x,y,full):
        pts={'A':(x,0),'B':(0,y)}
        if full:pts['C']=(x,y)
        return panel(f'Прямоугольник: a={x}, b={y}' if full else 'Соседние стороны OA и OB',pts,'OA AC CB BO' if full else 'OA OB','',['AOB','OAC','ACB','CBO'] if full else ['AOB'])
    a=rectangle(4,2,False);b=rectangle(4,2,True);c=rectangle(2,5,True)
    second=lesson(1016,part='б',pages=[255],question='Построй прямоугольник OACB. Точка A лежит на положительной полуоси Ox, B — на положительной полуоси Oy; OA=a, OB=b. Найди координаты четырёх вершин.',
        answer='O=(0;0), A=(a;0), C=(a;b), B=(0;b), где a и b положительны. У C такая же абсцисса, как у A, и та же ордината, что у B.',
        hint='Проведи через A вертикаль, а через B горизонталь. Их пересечение — недостающая вершина C.',
        steps=[('Запиши известные точки','Длина OA=a откладывается вправо, OB=b вверх. Поэтому A=(a;0), B=(0;b). Обход задан в порядке O,A,C,B.','Стороны прямоугольника, смежные с O, лежат вдоль осей.'),
               ('Найди пересечение прямых','На вертикали через A абсцисса постоянна и равна a. На горизонтали через B ордината постоянна и равна b. Обеим прямым принадлежит C=(a;b).','Противоположные стороны прямоугольника параллельны.'),
               ('Проверь на другом размере','На первой модели a=4,b=2; на второй a=2,b=5. В обоих случаях от A к C изменяется только высота, а от C к B — только абсцисса.','Порядок координат сохраняется и при обмене длин сторон.')],
        frames=[a,a,b,c],cases=[a,b,c], prompts=[('Для a=4,b=2 найди xC.','4','Вертикаль через A задаёт x=a.'),('Теперь a=2,b=5. Какова ордината середины AC?','2,5','Концы AC лежат на высотах 0 и 5; возьми полусумму.')])
    return [first,second]


def voyage():
    # Use 25 km per authored grid square. The printed A is at x=30 km on the east axis.
    pts={'A':(1.2,0),'K':(5.2,0),'B':(5.2,3)}
    first=panel('Сначала на восток',{k:pts[k] for k in 'AK'},'', 'AK')
    turn=panel('Поворот на север',pts,'','AK KB',['AKB'])
    resultant=panel('Одно перемещение из A в B',pts,'','AK KB AB',['AKB'])
    shifted=panel('Другое место старта при тех же двух ходах',{'A':(-2,-1),'K':(2,-1),'B':(2,2)},'','AK KB AB',['AKB'])
    entry=lesson(1017,pages=[256],unit='25 км',question='Корабль из A проходит 100 км на восток, затем 75 км на север. На координатной карте восток задаёт положительное направление x, север — положительное направление y. Изобрази одно результирующее перемещение и найди его координаты в километрах.',
        answer='Проведи стрелку из пункта отправления в конечный пункт. Координаты вектора равны (100;75) км. Старт необязательно находится в начале координат. Если A=(30;0), то B=(130;75), а B−A=(100;75).',
        hint='Вопрос относится к перемещению. Вычти положение старта из положения финиша по каждой оси.',
        steps=[('Отложи первый переход','На нашей карте клетка равна 25 км. От A отложи четыре клетки вправо. За этот переход ордината не менялась.','Сто километров к востоку соответствуют векторам с горизонтальной составляющей +100 км.'),
               ('Добавь второй переход','Из места поворота K отложи три клетки вверх. Перемещение AK=(100;0) км, а KB=(0;75) км. Стрелка AB из A в B соединяет начало и конец всего пути.','Сложение векторов соответствует последовательному движению.'),
               ('Отдели точку от вектора','Из A=(30;0) корабль приходит в B=(130;75). Если сдвинуть весь маршрут, точки получат другие координаты, а разность B−A останется (100;75). Длина прямого смещения 125 км также отличается от пройденного пути 175 км.','Свободный вектор не зависит от места начала одинакового маршрута.')],
        frames=[first,first,turn,resultant],cases=[first,resultant,shifted],prompts=[('Сколько километров составляет вертикальная компонента AB?','75','Север — положительное направление оси y; второй ход равен 75 км.'),('Новая отправная точка имеет x=−50 км. После тех же двух переходов какова абсцисса финиша в километрах?','50','К начальной абсциссе −50 прибавь 100; переход на север x не меняет.')])
    return pair_answer(entry,(100,75),'Введи перемещение в километрах. При результате 130;75 записаны координаты финиша; вычти координаты старта. Длина пути 175 тоже не заменяет пару координат.')


def square():
    p={'P':(-3,3),'M':(3,-3),'N':(3,3),'Q':(-3,-3)}
    diagon=panel('Отрази P относительно O',{'P':p['P'],'M':p['M']},'PM')
    d=panel('Две взаимно перпендикулярные диагонали',p,'PM NQ','',['PON'])
    around=panel('Обход M–N–P–Q',p,'MN NP PQ QM PM NQ','',['MNP','NPQ','PQM','QMN','PON'])
    swap=panel('Та же фигура с обратным обходом',{**p,'N':p['Q'],'Q':p['N']},'MN NP PQ QM PM NQ','',['MNP','NPQ','PQM','QMN','PON'])
    return lesson(1018,pages=[256],question='Для квадрата MNPQ известны P=(−3;3) и точка пересечения диагоналей O=(0;0). Построй квадрат и укажи координаты M, N, Q. Объясни, как выбор направления обхода влияет на названия вершин.',
        answer='M=(3;−3). Другие две вершины имеют координаты (3;3) и (−3;−3). Можно назвать первую N, вторую Q или наоборот. Обе нумерации дают квадрат с последовательным обходом M,N,P,Q.',
        hint='Сначала найди противоположную P вершину. Поверни радиус-вектор OP вокруг O на 90° в каждую сторону, чтобы получить остальные две.',
        steps=[('Отрази через центр','В квадрате вершины M и P противоположны. Диагонали делятся в точке пересечения пополам. Обе координаты M противоположны координатам P, так что M=(3;−3).','Точка O является серединой MP.'),
               ('Построй вторую диагональ','На одной диагонали располагаются (−3;3) и (3;−3). Перпендикулярная ей прямая через O имеет вид y=x. На ней на том же расстоянии от O лежат (3;3) и (−3;−3).','У квадрата диагонали равны и взаимно перпендикулярны.'),
               ('Выбери обход и проверь','При N=(3;3) получаем Q=(−3;−3); обратное назначение также верно. В обоих вариантах идут четыре стороны длины 6, а обе диагонали проходят через O.','Условие не фиксирует направление обхода границы квадрата.')],
        frames=[diagon,diagon,d,around],cases=[diagon,around,swap],prompts=[('Какова абсцисса вершины M?','3','O — середина MP; абсциссы M и P противоположны.'),('В другом квадрате с тем же центром P=(−4;4). Какова длина его стороны?','8','После поворота OP на 90° получается (4;4); длина горизонтальной стороны равна 4−(−4).')])


def isosceles():
    def drawing(a,h,full):
        return panel(f'Основание {2*a}, высота {h}' if full else 'Основание расположено на Ox',{'A':(-a,0),'B':(a,0),'C':(0,h)},'AB AC CB CO' if full else 'AB','',['AOC','BOC'] if full else [])
    a=drawing(3,4,False);b=drawing(3,4,True);c=drawing(4,2,True)
    return lesson(1019,pages=[256],question='В равнобедренном ABC основание AB лежит на оси x, A левее O и B правее O. Высота CO лежит на положительной полуоси y. Найди координаты вершин, если AB=2a и CO=h.',
        answer='A=(−a;0), B=(a;0), C=(0;h). Высота из вершины равнобедренного треугольника делит основание на две равные части.',
        hint='Проверь, длина какого именно отрезка равна 2a; от начала координат до каждого конца основания расстояние вдвое меньше.',
        steps=[('Раздели основание пополам','В равнобедренном треугольнике высота к основанию является медианой. Поэтому OA=OB=AB/2=a.','Равные боковые стороны и общая высота дают два равных прямоугольных треугольника.'),
               ('Расставь знаки','У обеих точек основания y=0. Вершина A слева от O, поэтому xA=−a. Вершина B справа, поэтому xB=a. Расстояние по основанию a−(−a)=2a.','Длина неотрицательна, а координата точки зависит от стороны оси.'),
               ('Найди положение C','Вершина C лежит над O на Oy. Значит xC=0, yC=h. На двух схемах поменялись ширина и высота, но точка O осталась серединой AB.','Перпендикуляр к горизонтальному основанию через O совпадает с осью y.')],
        frames=[a,a,b,b],cases=[a,b,c],prompts=[('При a=3 найди xA.','-3','Точка A слева от O; величина смещения равна a.'),('В новой фигуре AB=12, h=2. Какова абсцисса B?','6','Раздели длину всего основания 12 пополам.')])


def parallelogram():
    # A and the origin O coincide. Keep one mark labelled A=O instead of two labels at the same point.
    p={'B':(5,0),'C':(12,-3),'D':(7,-3)}
    a=panel('Известные вершины',{'B':p['B'],'C':p['C']},'OB BC')
    b=panel('Перенеси BC в начальную вершину',p,'OB CD','BC OD')
    c=panel('Замкни контур параллелограмма',p,'OB BC CD DO')
    entry=lesson(1020,pages=[256],question='В параллелограмме ABCD подряд названы вершины A=(0;0), B=(5;0), C=(12;−3). Найди координаты D и проверь параллельность обеих пар противоположных сторон.',
        answer='Вектор BC=(12−5;−3−0)=(7;−3). Вектор AD равен BC. При A=(0;0) получаем D=(7;−3). Проверка: DC=(5;0)=AB.',
        hint='У противоположных сторон сравни стрелки, направленные одинаково: AD=BC и DC=AB.',
        steps=[('Вычисли перемещение','Из B в C нужно пройти семь единиц вправо и три вниз. Значит BC=(7;−3). Точка A совпадает с началом координат.','У координат вектора в каждой позиции вычитай начало из конца.'),
               ('Построй D','Отложи от A ту же стрелку. Конец имеет x=0+7=7, y=0−3=−3. Получили D=(7;−3).','Противоположные стороны параллелограмма равны и параллельны; в AD и BC согласованы направления.'),
               ('Проверь вторую пару','Вычисли DC=(12−7;−3−(−3))=(5;0). Это действительно AB. Если ошибочно взять CB, вершина окажется по другую сторону от A и эта проверка не сойдётся.','В общем виде D=A+C−B при последовательном обходе A,B,C,D.')],
        frames=[a,a,b,c],cases=[a,b,c],prompts=[('Чему равна горизонтальная составляющая BC?','7','Из абсциссы точки C вычти абсциссу точки B.'),('В новом параллелограмме xA=−2, xB=4, xC=9. Найди xD.','3','К xA=−2 прибавь разность 9−4.')])
    for key,label in entry['visualization']['model']['labels'].items():
        if label=='O':entry['visualization']['model']['labels'][key]='A=O'
    return pair_answer(entry,(7,-3),'Вычти B из C, затем прибавь координаты A. Ответ 17;−3 складывает B и C; ответ −7;3 соответствует направлению CB.')


def build():
    return {'bookId':BOOK,'lessons':formulas()+axes()+[voyage(),square(),isosceles(),parallelogram()]}


if __name__=='__main__':
    parser=argparse.ArgumentParser();parser.add_argument('--check',action='store_true')
    text=json.dumps(build(),ensure_ascii=False,separators=(',',':'))+'\n'
    if parser.parse_args().check:assert OUT.read_text()==text
    else:OUT.write_text(text)
